<style>
:root{
  --onyx:#0E0E10; --charcoal:#17171A; --graphite:#26262B;
  --crimson:#C4202E; --oxblood:#8E1622;
  --gold:#B8975A; --gold-light:#D9C08A;
  --ivory:#F5F1E8; --ivory-deep:#EFE9DC; --stone:#B9B0A0;
  --display:'Playfair Display',Georgia,serif;
  --text:'Lora',Georgia,serif;
  --ui:'Inter',Arial,sans-serif;
  --gut:clamp(20px,5vw,80px);
  --rule:rgba(184,151,90,.28);
  --rule-dark:rgba(14,14,16,.16);
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;background:var(--onyx);color:var(--ivory);font-family:var(--ui);font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased;overflow-x:hidden}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
h1,h2,h3,h4{font-family:var(--display);font-weight:400;letter-spacing:-.01em;margin:0}
p{margin:0 0 1.1em}
:focus-visible{outline:2px solid var(--gold-light);outline-offset:4px}
.skip{position:absolute;left:-9999px;top:0;z-index:200;background:var(--ivory);color:var(--onyx);padding:14px 22px;font-size:12px;letter-spacing:.16em;text-transform:uppercase}
.skip:focus{left:12px;top:12px}

.eyebrow{font-family:var(--ui);font-size:11px;font-weight:500;letter-spacing:.24em;text-transform:uppercase;color:var(--stone);display:flex;align-items:center;gap:12px;margin:0}
.eyebrow::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--crimson);flex:none}
.h2{font-size:clamp(28px,4.2vw,54px);line-height:1.12}
.lede{font-family:var(--text);font-size:clamp(16px,1.35vw,19px);line-height:1.75}

.btn{display:inline-flex;align-items:center;gap:10px;font-family:var(--ui);font-size:12px;font-weight:500;letter-spacing:.16em;text-transform:uppercase;padding:16px 30px;border:1px solid var(--gold);color:var(--ivory);background:transparent;transition:background .35s,color .35s,border-color .35s;cursor:pointer}
.btn:hover{background:var(--gold);color:var(--onyx)}
.btn--solid{background:var(--ivory);color:var(--onyx);border-color:var(--ivory)}
.btn--solid:hover{background:var(--crimson);border-color:var(--crimson);color:var(--ivory)}
.btn--dark{border-color:rgba(14,14,16,.4);color:var(--onyx)}
.btn--dark:hover{background:var(--onyx);color:var(--ivory);border-color:var(--onyx)}
.link-arrow{font-family:var(--ui);font-size:12px;letter-spacing:.16em;text-transform:uppercase;display:inline-flex;align-items:center;gap:12px;padding-bottom:6px;border-bottom:1px solid var(--rule);transition:border-color .3s,gap .3s}
.link-arrow:hover{border-color:var(--crimson);gap:20px}
.link-arrow span{color:var(--crimson)}

section{padding:clamp(64px,9vw,132px) var(--gut)}
.wrap{max-width:1320px;margin:0 auto}
.light{background:var(--ivory);color:var(--onyx)}
.light .eyebrow{color:#6b6459}
.light .lede{color:#33312d}

.rail{position:fixed;left:26px;top:0;bottom:0;width:1px;background:rgba(245,241,232,.12);z-index:40;pointer-events:none;display:none}
.rail__dot{position:absolute;left:-3.5px;top:0;width:8px;height:8px;border-radius:50%;background:var(--crimson);transition:top .12s linear;box-shadow:0 0 0 5px rgba(196,32,46,.14)}
@media(min-width:1180px){.rail{display:block}}

.announce{background:#08080A;border-bottom:1px solid rgba(245,241,232,.08);padding:11px var(--gut);display:flex;gap:8px 18px;justify-content:center;align-items:center;flex-wrap:wrap;font-size:11.5px;letter-spacing:.12em;text-transform:uppercase;color:var(--stone)}
.announce b{font-weight:400;color:var(--ivory)}
.announce a{color:var(--gold-light);border-bottom:1px solid var(--rule);padding-bottom:2px}
.announce a:hover{color:var(--crimson);border-color:var(--crimson)}
.announce .dot{width:5px;height:5px;border-radius:50%;background:var(--crimson);flex:none}

header{position:sticky;top:0;z-index:50;background:rgba(14,14,16,.85);backdrop-filter:blur(14px);border-bottom:1px solid rgba(245,241,232,.07)}
.nav{max-width:1560px;margin:0 auto;padding:0 var(--gut);display:flex;align-items:center;justify-content:space-between;gap:28px;height:78px}
.logo img{height:26px;width:auto}
.nav__links{display:none;gap:clamp(12px,1.5vw,24px);align-items:center}
.nav__links a{font-size:11.5px;letter-spacing:.13em;text-transform:uppercase;color:rgba(245,241,232,.72);padding:6px 0;border-bottom:1px solid transparent;transition:.3s;white-space:nowrap}
.nav__links a:hover{color:var(--ivory);border-color:var(--crimson)}
.nav__cta{display:none}
@media(min-width:1180px){.nav__links{display:flex}.nav__cta{display:inline-flex}}
.burger{display:flex;flex-direction:column;gap:5px;background:none;border:0;padding:10px;cursor:pointer}
.burger span{width:22px;height:1px;background:var(--ivory);display:block}
@media(min-width:1180px){.burger{display:none}}

/* hero */
.hero{position:relative;min-height:min(92vh,880px);display:flex;align-items:flex-end;padding:clamp(80px,14vh,160px) var(--gut) clamp(48px,8vh,88px);overflow:hidden}
.hero__bg{position:absolute;inset:0;z-index:0}
.hero__bg img{width:100%;height:100%;object-fit:cover;filter:saturate(.7) contrast(1.02)}
.hero__bg::after{content:"";position:absolute;inset:0;background:linear-gradient(100deg,rgba(14,14,16,.95) 0%,rgba(14,14,16,.8) 42%,rgba(14,14,16,.34) 100%),linear-gradient(to top,rgba(14,14,16,.92),transparent 46%)}
.hero__inner{position:relative;z-index:1;max-width:1320px;margin:0 auto;width:100%}
.hero h1{font-size:clamp(38px,6.4vw,86px);line-height:1.04;max-width:16ch;margin:26px 0 24px}
.hero h1 .accent{color:var(--gold-light)}
.hero .lede{max-width:56ch;color:rgba(245,241,232,.85)}
.hero__cta{display:flex;flex-wrap:wrap;gap:14px;margin-top:34px}
.hero__meta{display:flex;gap:26px;flex-wrap:wrap;margin-top:clamp(40px,6vh,72px);padding-top:22px;border-top:1px solid rgba(245,241,232,.13);font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:var(--stone)}

/* manifesto */
.manifesto{background:#0B0B0D}
.manifesto h2{font-size:clamp(30px,5.2vw,68px);line-height:1.1;max-width:20ch;margin:30px 0 0}
.manifesto__note{display:flex;gap:16px;margin-top:40px;max-width:56ch}
.manifesto__note::before{content:"";width:7px;height:7px;border-radius:50%;background:var(--crimson);margin-top:12px;flex:none}
.manifesto__note p{font-family:var(--text);font-size:17px;color:rgba(245,241,232,.72);margin:0}

/* split */
.split{display:grid;gap:clamp(34px,5vw,72px);align-items:center}
@media(min-width:960px){.split{grid-template-columns:1.05fr .95fr}}
.split__media{position:relative}
.split__media img{width:100%;aspect-ratio:4/5;object-fit:cover}
@media(min-width:960px){.split__media img{aspect-ratio:3/4}}
.split__media::after{content:"";position:absolute;inset:0;border:1px solid rgba(184,151,90,.45);transform:translate(16px,16px);pointer-events:none;z-index:-1}
.split h2{margin:22px 0 24px}
.split__body{max-width:56ch;font-family:var(--text);font-size:17px;line-height:1.8}

/* discipline list */
.disc{margin-top:30px;border-top:1px solid var(--rule-dark)}
.disc div{display:flex;gap:16px;align-items:center;padding:15px 0;border-bottom:1px solid var(--rule-dark);font-size:12.5px;letter-spacing:.14em;text-transform:uppercase}
.disc div::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--crimson);flex:none}

/* DNA cards */
.cards{display:grid;gap:1px;background:rgba(184,151,90,.22);margin-top:clamp(40px,5vw,60px)}
@media(min-width:700px){.cards{grid-template-columns:1fr 1fr}}
@media(min-width:1100px){.cards{grid-template-columns:repeat(4,1fr)}}
.card{background:var(--onyx);padding:clamp(28px,3vw,40px);position:relative;transition:background .4s}
.card:hover{background:var(--charcoal)}
.card::before{content:"";position:absolute;top:0;left:0;right:0;height:2px;background:var(--crimson);transform:scaleX(0);transform-origin:left;transition:transform .5s cubic-bezier(.2,.7,.3,1)}
.card:hover::before{transform:scaleX(1)}
.card__i{font-family:var(--ui);font-size:10.5px;letter-spacing:.22em;color:var(--gold);display:block;margin-bottom:22px}
.card h3{font-size:23px;margin-bottom:14px}
.card p{font-size:14.5px;color:rgba(245,241,232,.66);line-height:1.75;margin:0 0 16px}
.card ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px 14px}
.card li{font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--stone)}

/* markets */
.markets{display:flex;flex-wrap:wrap;gap:0;margin-top:clamp(34px,4vw,52px);border-top:1px solid rgba(184,151,90,.2)}
.market{flex:1 1 160px;padding:24px 20px 24px 0;border-bottom:1px solid rgba(184,151,90,.2);display:flex;align-items:baseline;gap:12px}
.market::before{content:"";width:7px;height:7px;border-radius:50%;background:var(--gold);flex:none;align-self:center}
.market.is-base::before{background:var(--crimson)}
.market b{font-weight:400;font-size:15px;letter-spacing:.14em;text-transform:uppercase}
.market.is-base b{color:var(--ivory)}
.market span{font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--stone)}
.markets-note{margin-top:26px;font-family:var(--text);font-style:italic;font-size:14px;color:rgba(185,176,160,.85);max-width:70ch}

/* leadership */
.leaders{display:grid;gap:clamp(24px,3vw,34px);margin-top:clamp(40px,5vw,60px)}
@media(min-width:620px){.leaders{grid-template-columns:1fr 1fr}}
@media(min-width:1080px){.leaders{grid-template-columns:repeat(4,1fr)}}
.leader__img{position:relative;border:1px solid rgba(184,151,90,.35);overflow:hidden}
.leader__img img{width:100%;aspect-ratio:3/4;object-fit:cover;object-position:top center;filter:grayscale(1) contrast(1.03);transition:filter .6s ease}
.leader:hover .leader__img img{filter:grayscale(0)}
.leader h3{font-family:var(--ui);font-size:13.5px;font-weight:500;letter-spacing:.14em;text-transform:uppercase;margin:20px 0 8px}
.leader .role{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--gold);margin:0 0 12px}
.leader p{font-family:var(--text);font-size:14.5px;color:rgba(245,241,232,.66);margin:0}
.leader__stat{margin-top:14px;padding-top:12px;border-top:1px solid rgba(184,151,90,.22);font-size:12px;color:var(--stone)}
.leader__stat b{font-family:var(--display);font-size:20px;color:var(--ivory);font-weight:400;margin-right:8px}

/* stats */
.stats{background:var(--charcoal);border-top:1px solid rgba(184,151,90,.2)}
.stats__grid{display:grid;grid-template-columns:1fr;margin-top:44px}
@media(min-width:640px){.stats__grid{grid-template-columns:1fr 1fr}}
@media(min-width:1000px){.stats__grid{grid-template-columns:repeat(4,1fr)}}
.stat{padding:30px 30px 30px 0;border-top:1px solid rgba(184,151,90,.18)}
@media(min-width:1000px){.stat{border-top:0;border-left:1px solid rgba(184,151,90,.18);padding:8px 30px}.stat:first-child{border-left:0;padding-left:0}}
.stat__n{font-family:var(--display);font-size:clamp(38px,4.6vw,58px);line-height:1}
.stat__n em{font-style:normal;color:var(--crimson)}
.stat__l{font-size:12.5px;color:var(--stone);line-height:1.55;margin-top:12px;max-width:26ch}
.stats__note{margin-top:36px;padding-top:20px;border-top:1px solid rgba(245,241,232,.09);font-size:12.5px;color:rgba(185,176,160,.82);max-width:80ch;font-style:italic;font-family:var(--text)}

/* sectors */
.sectors{display:grid;gap:1px;background:var(--rule-dark);margin-top:clamp(34px,4vw,52px)}
@media(min-width:620px){.sectors{grid-template-columns:1fr 1fr}}
@media(min-width:1080px){.sectors{grid-template-columns:repeat(4,1fr)}}
.sector{background:var(--ivory);padding:clamp(26px,3vw,38px) clamp(20px,2vw,28px);position:relative;transition:background .4s}
.sector:hover{background:var(--ivory-deep)}
.sector i{font-style:normal;font-family:var(--ui);font-size:10.5px;letter-spacing:.22em;color:#8a8071;display:block;margin-bottom:26px}
.sector h3{font-size:21px;line-height:1.25}
.sector p{font-family:var(--text);font-size:14.5px;color:#4a4741;margin:12px 0 0}

/* corridors */
.corridors{display:grid;gap:0;margin-top:clamp(34px,4vw,50px);border-top:1px solid var(--rule-dark)}
@media(min-width:820px){.corridors{grid-template-columns:1fr 1fr;column-gap:64px}}
.corridor{padding:26px 0;border-bottom:1px solid var(--rule-dark)}
.corridor i{font-style:normal;font-size:10.5px;letter-spacing:.22em;text-transform:uppercase;color:#8a8071;display:block;margin-bottom:12px}
.corridor h3{font-size:26px}
.corridor p{font-family:var(--text);font-size:15px;color:#4a4741;margin:10px 0 0;max-width:44ch}

/* horizons */
.horizons{display:grid;gap:clamp(28px,4vw,56px);margin-top:clamp(34px,4vw,50px)}
@media(min-width:820px){.horizons{grid-template-columns:repeat(3,1fr)}}
.horizon h4{font-family:var(--ui);font-size:10.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--gold);font-weight:500;margin:0 0 18px;padding-bottom:14px;border-bottom:1px solid rgba(184,151,90,.25)}
.horizon ul{list-style:none;margin:0;padding:0;display:grid;gap:12px}
.horizon li{display:flex;align-items:center;gap:14px;font-size:18px;letter-spacing:.1em;text-transform:uppercase}
.horizon li::before{content:"";width:7px;height:7px;border-radius:50%;border:1px solid var(--stone);flex:none}
.horizon li.on::before{background:var(--crimson);border-color:var(--crimson)}
.horizon li.on{color:var(--ivory)}
.horizon li:not(.on){color:rgba(245,241,232,.6)}

/* teaser */
.teaser{background:var(--onyx);text-align:center;position:relative}
.teaser::before{content:"";position:absolute;left:50%;top:0;width:1px;height:clamp(40px,7vw,90px);background:linear-gradient(var(--crimson),transparent)}
.teaser__dot{width:9px;height:9px;border-radius:50%;background:var(--crimson);margin:0 auto 30px}
.teaser .eyebrow{justify-content:center}
.teaser h2{max-width:18ch;margin:22px auto 26px}
.teaser .lede{max-width:60ch;margin:0 auto 36px;color:rgba(245,241,232,.76)}
.teaser small{display:block;margin-top:30px;font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:rgba(185,176,160,.65)}

/* closing */
.closing{background:#08080A;text-align:center;padding:clamp(70px,10vw,150px) var(--gut)}
.closing ul{list-style:none;margin:0 0 40px;padding:0;display:flex;flex-wrap:wrap;justify-content:center;gap:14px 34px}
.closing li{font-size:11px;letter-spacing:.22em;text-transform:uppercase;color:var(--gold)}
.closing h2{font-size:clamp(30px,5.4vw,68px);line-height:1.1;max-width:16ch;margin:0 auto}

/* enquiry */
.enq{display:grid;gap:clamp(36px,5vw,80px)}
@media(min-width:960px){.enq{grid-template-columns:1fr 1fr}}
.contact-row{display:flex;gap:20px;justify-content:space-between;align-items:baseline;padding:20px 0;border-bottom:1px solid var(--rule-dark)}
.contact-row dt{font-size:10.5px;letter-spacing:.2em;text-transform:uppercase;color:#6b6459;flex:none;width:112px}
.contact-row dd{margin:0;text-align:right;font-family:var(--text);font-size:16.5px}
.contact-row dd a{border-bottom:1px solid var(--rule-dark);transition:.3s}
.contact-row dd a:hover{border-color:var(--crimson);color:var(--crimson)}

footer{background:#08080A;padding:clamp(56px,7vw,90px) var(--gut) 34px;border-top:1px solid rgba(184,151,90,.2)}
.foot__top{display:grid;gap:44px}
@media(min-width:900px){.foot__top{grid-template-columns:1.3fr 1fr 1fr}}
.foot__tag{font-family:var(--display);font-size:clamp(20px,2.2vw,28px);margin:24px 0 0;max-width:18ch}
.foot h4{font-family:var(--ui);font-size:10.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--gold);margin:0 0 20px;font-weight:500}
.foot ul{list-style:none;margin:0;padding:0;display:grid;gap:11px}
.foot a{font-size:14px;color:rgba(245,241,232,.7)}
.foot a:hover{color:var(--ivory)}
.social{display:flex;gap:14px;margin-top:26px}
.social a{
  width:38px;height:38px;display:grid;place-items:center;
  border:1px solid rgba(184,151,90,.35);color:var(--stone);
  transition:background .35s,color .35s,border-color .35s}
.social a:hover,.social a:focus-visible{background:var(--crimson);border-color:var(--crimson);color:var(--ivory)}
.social svg{width:16px;height:16px;fill:currentColor;display:block}
.foot__bottom{margin-top:clamp(46px,6vw,72px);padding-top:24px;border-top:1px solid rgba(245,241,232,.09);display:flex;flex-wrap:wrap;gap:12px 26px;justify-content:space-between;font-size:11.5px;color:rgba(185,176,160,.7)}

.mobile-cta{position:fixed;left:0;right:0;bottom:0;z-index:60;display:flex;border-top:1px solid rgba(184,151,90,.3);background:rgba(8,8,10,.95);backdrop-filter:blur(12px)}
.mobile-cta a{flex:1;text-align:center;padding:15px 8px;font-size:11px;letter-spacing:.16em;text-transform:uppercase}
.mobile-cta a+a{border-left:1px solid rgba(245,241,232,.12);color:var(--gold-light)}
@media(min-width:1180px){.mobile-cta{display:none}}
@media(max-width:1179px){body{padding-bottom:52px}}

.reveal-media{clip-path:inset(0 0 0% 0)}
/* legacy statement band */
.legacy{background:var(--ivory);color:var(--onyx);padding:clamp(52px,6.5vw,96px) var(--gut)}
.legacy__grid{display:grid;gap:clamp(26px,4vw,64px);align-items:end}
@media(min-width:920px){.legacy__grid{grid-template-columns:1.15fr .85fr}}
.legacy h2{font-size:clamp(30px,4.6vw,60px);line-height:1.08;max-width:15ch}
.legacy h2 .q{display:block;color:var(--bronze,#8C6A43)}
.legacy h2 em{font-style:normal;color:#8C6A43}
.legacy__body{font-family:var(--text);font-size:16.5px;line-height:1.8;color:#4a4741;max-width:46ch}
.legacy__rule{height:1px;background:var(--rule-dark);margin:clamp(28px,3.4vw,44px) 0 0}
.legacy__disc{display:flex;flex-wrap:wrap;gap:10px 0;margin-top:26px;border-top:0}
.legacy__disc span{flex:1 1 auto;min-width:150px;font-size:10.5px;letter-spacing:.2em;text-transform:uppercase;color:#6b6459;display:flex;align-items:center;gap:10px}
.legacy__disc span::before{content:"";width:5px;height:5px;border-radius:50%;background:var(--crimson);flex:none}
/* lead capture form */
.form-panel{background:#fff;border:1px solid var(--rule-dark);padding:clamp(26px,3.4vw,44px)}
.form-panel h3{font-size:24px;margin-bottom:10px}
.form-panel .form-intro{font-family:var(--text);font-size:14.5px;color:#5a564e;margin-bottom:28px}
.field{margin-bottom:24px;position:relative}
.field label{display:block;font-size:10.5px;letter-spacing:.2em;text-transform:uppercase;color:#6b6459;margin-bottom:8px}
.field input,.field select,.field textarea{
  width:100%;border:0;border-bottom:1px solid rgba(14,14,16,.22);background:transparent;
  font-family:var(--text);font-size:16px;color:var(--onyx);padding:8px 0 10px;border-radius:0;
  transition:border-color .3s;appearance:none}
.field select{font-family:var(--ui);font-size:15px;background-image:linear-gradient(45deg,transparent 50%,#6b6459 50%),linear-gradient(135deg,#6b6459 50%,transparent 50%);background-position:calc(100% - 12px) 16px,calc(100% - 7px) 16px;background-size:5px 5px;background-repeat:no-repeat;padding-right:26px}
.field textarea{resize:vertical;min-height:88px}
.field input:focus,.field select:focus,.field textarea:focus{outline:none;border-bottom-color:var(--crimson)}
.field .err{display:none;font-size:12px;color:var(--oxblood);margin-top:7px}
.field.invalid input,.field.invalid select,.field.invalid textarea{border-bottom-color:var(--oxblood)}
.field.invalid .err{display:block}
.field--row{display:grid;gap:24px}
@media(min-width:560px){.field--row{grid-template-columns:1fr 1fr}.field--row .field{margin-bottom:0}}
.consent{display:flex;gap:12px;align-items:flex-start;margin:6px 0 26px}
.consent input{width:16px;height:16px;flex:none;margin-top:3px;accent-color:var(--crimson)}
.consent label{font-size:13px;letter-spacing:0;text-transform:none;color:#4a4741;line-height:1.6;margin:0}
.consent a{border-bottom:1px solid var(--rule-dark)}
.consent.invalid label{color:var(--oxblood)}
.form-hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.form-msg{margin-top:20px;padding:16px 18px;border-inline-start:2px solid var(--crimson);background:var(--ivory-deep);font-family:var(--text);font-size:14.5px;display:none}
.form-msg.show{display:block}
.form-msg.is-error{border-color:var(--oxblood)}
.form-foot{font-size:12px;color:#6b6459;margin:18px 0 0}
.counter{font-variant-numeric:tabular-nums}
[data-parallax]{will-change:transform}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
</style>
</head>
<body>

<a class="skip" href="#top">Skip to content</a>
<div class="rail" aria-hidden="true"><div class="rail__dot" id="railDot"></div></div>

<div class="announce">
  <span class="dot" aria-hidden="true"></span>
  <b>A new Business Bay opportunity is coming soon.</b>
  <a href="#coming-soon">Join the private launch list</a>
</div>

<header>
  <nav class="nav" aria-label="Primary">
    <a class="logo" href="#top" aria-label="Business Bay Developments — home"><img src="data:image/png;base64," alt="Business Bay Developments"></a>
    <div class="nav__links">
      <a href="#legacy">About</a>
      <a href="#leadership">Leadership</a>
      <a href="#dna">Our Approach</a>
      <a href="#focus">New Capital</a>
      <a href="#sectors">What We Build</a>
      <a href="#horizons">Next Horizons</a>
      <a href="/journal">Journal</a>
      <a href="#coming-soon">Coming Soon</a>
      <a href="#contact">Contact</a>
    </div>
    <a class="btn nav__cta" href="#contact">Contact our team</a>
    <button class="burger" aria-label="Open menu" aria-expanded="false"><span></span><span></span><span></span></button>
  </nav>
</header>

<main id="top" role="main">

<!-- HERO -->
<section class="hero">
  <div class="hero__bg"><img src="data:image/jpeg;base64," alt="Twilight view across a still reflecting pool toward a distant city skyline"></div>
  <div class="hero__inner">
    <p class="eyebrow">Business Bay Developments · Egyptian Real Estate Developer</p>
    <h1>Global experience.<br><span class="accent">One development vision.</span></h1>
    <p class="lede">A new-generation Egyptian real-estate developer bringing together decades of experience across development, engineering, commercial strategy, customer experience and operations.</p>
    <div class="hero__cta">
      <a class="btn btn--solid" href="#think" data-ev="hero_cta_click">Discover Business Bay</a>
      <a class="btn" href="#contact" data-ev="hero_cta_click">Contact our team</a>
    </div>
    <div class="hero__meta">
      <span>Luxury residential · Hospitality · Commercial</span>
      <span>New Cairo &amp; the New Administrative Capital</span>
      <span>Cairo, Egypt</span>
    </div>
  </div>
</section>

<!-- A NEW COMPANY, BUILT ON A PROVEN LEGACY -->
<section class="legacy" id="legacy">
  <div class="wrap legacy__grid">
    <div>
      <p class="eyebrow">Who we are</p>
      <h2 style="margin-top:24px">A new company. <em>Built on a proven legacy.</em></h2>
    </div>
    <div>
      <div class="legacy__body">
        <p>Business Bay Developments is new. The people behind it are not. Four founders, four disciplines, and careers spent delivering the buildings, the engineering and the commercial networks that most developers have to hire in.</p>
        <p style="margin-bottom:0">That is the whole proposition: the ambition of a new company, underwritten by a record that already exists.</p>
      </div>
    </div>
  </div>
  <div class="wrap">
    <div class="legacy__rule"></div>
    <div class="legacy__disc">
      <span>Development &amp; customer intelligence</span>
      <span>Development &amp; construction</span>
      <span>Engineering &amp; international expertise</span>
      <span>Commercial &amp; retail operations</span>
    </div>
  </div>
</section>

<!-- ACT I — HOW WE THINK -->
<section class="manifesto" id="think">
  <div class="wrap">
    <p class="eyebrow">Act I — How we think</p>
    <h2>Great developments are not defined by buildings. They are defined by the experiences they create.</h2>
    <div class="manifesto__note">
      <p>At Business Bay, every development starts with understanding people — how they live, work, invest, stay and experience a destination.</p>
    </div>
  </div>
</section>

<!-- IT STARTS WITH PEOPLE -->
<section class="light">
  <div class="wrap split">
    <div>
      <p class="eyebrow">It starts with people</p>
      <h2 class="h2">Before we develop spaces, we understand people.</h2>
      <div class="split__body">
        <p>Demand is not a spreadsheet assumption. Before a line is drawn, we study how people actually behave — what they buy, why they stay, what they will still value in ten years. Everything that follows is built on that reading.</p>
      </div>
      <div class="disc">
        <div>Customer behaviour</div>
        <div>Customer experience</div>
        <div>Market intelligence</div>
        <div>Investment behaviour</div>
        <div>Lifestyle &amp; hospitality</div>
      </div>
    </div>
    <div class="split__media">
      <img src="data:image/jpeg;base64," alt="A quiet boardroom at golden hour with a long timber table and a city view beyond full-height glass">
    </div>
  </div>
</section>

<!-- OUR DNA -->
<section id="dna">
  <div class="wrap">
    <p class="eyebrow">Our DNA</p>
    <h2 class="h2" style="margin-top:22px;max-width:22ch">We understand. We develop. We deliver. We operate.</h2>
    <div class="cards">
      <article class="card"><span class="card__i">01</span><h3>Understand</h3><p>We study the market, the location, the customer and the long-term opportunity before shaping a development.</p><ul><li>Customer</li><li>Market</li><li>Investment</li></ul></article>
      <article class="card"><span class="card__i">02</span><h3>Develop</h3><p>Insight becomes architecture, planning, product and experience — designed for real demand rather than for a brochure.</p><ul><li>Concept</li><li>Product</li><li>Strategy</li></ul></article>
      <article class="card"><span class="card__i">03</span><h3>Deliver</h3><p>Delivery is a discipline of detail: sequencing, supervision and the unglamorous work of keeping design intent intact.</p><ul><li>Engineering</li><li>Construction</li><li>Quality</li></ul></article>
      <article class="card"><span class="card__i">04</span><h3>Operate</h3><p>Long-term value depends not only on what is built, but on how the asset is experienced, managed and commercially run.</p><ul><li>Commercial</li><li>Hospitality</li><li>Experience</li><li>Asset value</li></ul></article>
    </div>
  </div>
</section>

<!-- WHERE OUR EXPERIENCE COMES FROM -->
<section class="light">
  <div class="wrap">
    <div class="split">
      <div>
        <p class="eyebrow">Act II — Where our experience comes from</p>
        <h2 class="h2">Our DNA wasn't built in one market.</h2>
        <div class="split__body">
          <p>Egypt is where we build and where our judgement is grounded. Our standards come from a wider professional exposure — to international specification, hospitality operating culture, and markets where quality is assumed rather than promised.</p>
        </div>
      </div>
      <div class="split__media">
        <img src="data:image/jpeg;base64," alt="A high-rise interior looking out over an international city skyline at sunrise">
      </div>
    </div>
    <div class="markets">
      <div class="market is-base"><b>Egypt</b><span>Development base</span></div>
      <div class="market"><b>UAE</b><span>Engineering</span></div>
      <div class="market"><b>Saudi Arabia</b><span>Commercial</span></div>
      <div class="market"><b>Kuwait</b><span>Construction</span></div>
      <div class="market"><b>Lebanon</b><span>Commercial</span></div>
      <div class="market"><b>Italy</b><span>Commercial</span></div>
    </div>
    <p class="markets-note">The markets above represent the leadership team's professional experience — not Business Bay offices or completed Business Bay projects.</p>
  </div>
</section>

<!-- LEADERSHIP -->
<section id="leadership">
  <div class="wrap">
    <p class="eyebrow">Leadership</p>
    <h2 class="h2" style="margin-top:22px">Four journeys. One Business Bay.</h2>
    <p class="lede" style="max-width:56ch;margin-top:20px;color:rgba(245,241,232,.72)">Decades of experience. Different disciplines. One shared development vision.</p>
    <div class="leaders">
      <article class="leader">
        <div class="leader__img"><img src="data:image/jpeg;base64," alt="Portrait of Amir Sami"></div>
        <h3>Amir Sami</h3>
        <p class="role">Co-Founder &amp; CEO</p>
        <p>Development and customer intelligence. Commercial leadership across New Cairo residential development, with a career built on reading demand before designing for it.</p>
        <div class="leader__stat"><b>18+</b>Years in real-estate leadership</div>
      </article>
      <article class="leader">
        <div class="leader__img"><img src="data:image/jpeg;base64," alt="Portrait of Eng. Talaat Gawargious"></div>
        <h3>Eng. Talaat Gawargious</h3>
        <p class="role">Co-Founder &amp; Board Member</p>
        <p>Development and construction. Founder of a Cairo construction and real-estate investment practice, with delivery across Nasr City and New Cairo.</p>
        <div class="leader__stat"><b>150+</b>Residential buildings and towers</div>
      </article>
      <article class="leader">
        <div class="leader__img"><img src="data:image/jpeg;base64," alt="Portrait of Eng. Emad El Sherbiny"></div>
        <h3>Eng. Emad El Sherbiny</h3>
        <p class="role">Engineering Partner</p>
        <p>Engineering and international expertise. Chairman of an engineering consultancy practising across the UAE, Saudi Arabia and Egypt, with high-rise and hospitality specialism.</p>
        <div class="leader__stat"><b>1996</b>Practice established</div>
      </article>
      <article class="leader">
        <div class="leader__img"><img src="data:image/jpeg;base64," alt="Portrait of Eng. Wael Shawkat"></div>
        <h3>Eng. Wael Shawkat</h3>
        <p class="role">Commercial Partner</p>
        <p>Commercial and retail operations. Retail mix, leasing and destination management across four markets, with a brand network built over decades.</p>
        <div class="leader__stat"><b>550+</b>Brands in the commercial network</div>
      </article>
    </div>
    <div style="margin-top:44px"><a class="link-arrow" href="#leadership">Read the full leadership profiles <span>→</span></a></div>
  </div>
</section>

<!-- IN NUMBERS -->
<section class="stats">
  <div class="wrap">
    <p class="eyebrow">In numbers</p>
    <div class="stats__grid">
      <div class="stat"><div class="stat__n"><span class="counter" data-count="18">18</span><em>+</em></div><div class="stat__l">Years of real-estate leadership</div></div>
      <div class="stat"><div class="stat__n"><span class="counter" data-count="25">25</span><em>+</em></div><div class="stat__l">Years of development and construction experience</div></div>
      <div class="stat"><div class="stat__n"><span class="counter" data-count="150">150</span><em>+</em></div><div class="stat__l">Residential buildings and towers</div></div>
      <div class="stat"><div class="stat__n"><span class="counter" data-count="550">550</span><em>+</em></div><div class="stat__l">Brands in the commercial network</div></div>
    </div>
    <p class="stats__note">These figures represent the professional experience of Business Bay Developments' founders and leadership team across their careers, and should not be read as completed Business Bay Developments projects.</p>
  </div>
</section>

<!-- WHAT WE BUILD -->
<section class="light" id="sectors">
  <div class="wrap">
    <div class="split" style="grid-template-columns:1fr;gap:24px">
      <div>
        <p class="eyebrow">From experience to development</p>
        <h2 class="h2" style="margin-top:22px;max-width:16ch">Beyond buildings. <em style="font-style:normal;color:#8C6A43">We shape destinations.</em></h2>
        <p class="lede" style="max-width:58ch;margin-top:22px">We build destinations, not square metres. Business Bay develops concept-driven places designed around experience, operation and long-term asset value.</p>
      </div>
    </div>
    <div class="sectors">
      <div class="sector"><i>01</i><h3>Luxury residential</h3><p>Homes planned for how people actually live, specified to age well and hold their standing.</p></div>
      <div class="sector"><i>02</i><h3>Hospitality</h3><p>Hotels and hotel apartments conceived to international operating standards from the first study.</p></div>
      <div class="sector"><i>03</i><h3>Premium commercial</h3><p>Administrative and retail space shaped by commercial strategy, tenant mix and real footfall logic.</p></div>
      <div class="sector"><i>04</i><h3>Mixed-use destinations</h3><p>Integrated schemes where residential, commercial and hospitality reinforce one another.</p></div>
    </div>
  </div>
</section>

<!-- LAND BANK & FOCUS -->
<section id="focus" class="light" style="background:var(--ivory-deep)">
  <div class="wrap">
    <p class="eyebrow">Land bank &amp; strategic focus</p>
    <h2 class="h2" style="margin-top:22px;max-width:20ch">Positioned in Egypt's two growth corridors.</h2>
    <div class="corridors">
      <div class="corridor">
        <i>Corridor 01</i>
        <h3>New Cairo</h3>
        <p>An established east-Cairo market with mature demand, where our leadership has developed and delivered for years.</p>
      </div>
      <div class="corridor">
        <i>Corridor 02</i>
        <h3>New Administrative Capital</h3>
        <p>A capital being developed as a major centre for government, finance, business, diplomacy, education, healthcare and lifestyle — creating a new urban ecosystem with relevance for Egypt, Africa and international markets.</p>
      </div>
    </div>
    <div style="margin-top:46px;max-width:62ch">
      <p class="eyebrow" style="margin-bottom:18px">Strategic focus</p>
      <p class="lede">Hospitality-led development, built to an international hotel concept: hotels and hotel apartments, international operator standards, and mixed-use destinations where the operating model is designed alongside the architecture.</p>
      <p style="font-family:var(--text);font-style:italic;font-size:14px;color:#5a564e;margin-top:24px">The New Administrative Capital remains an evolving destination. Infrastructure, occupancy, commercial activity and market performance will develop over time, and individual investment outcomes depend on the specific asset, final terms, market conditions and applicable laws.</p>
    </div>
  </div>
</section>

<!-- NEXT HORIZONS -->
<section id="horizons">
  <div class="wrap">
    <p class="eyebrow">Act IV — What's next</p>
