</div>

<script>
    (function(){
        "use strict";

        var reduced = window.matchMedia(
            "(prefers-reduced-motion: reduce)"
        ).matches;

        /* ---------- analytics stubs ---------- */
        document.querySelectorAll("[data-ev]").forEach(function(el){
            el.addEventListener("click", function(){
                (window.dataLayer = window.dataLayer || []).push({
                    event: el.dataset.ev
                });
            });
        });

        /* ---------- crimson dot rail ---------- */
        var dot = document.getElementById("railDot");

        if (dot && !reduced) {
            var ticking = false;

            function moveDot(){
                var h = document.documentElement;

                var p =
                    h.scrollTop /
                    (h.scrollHeight - h.clientHeight || 1);

                dot.style.transform =
                    "translateY(" +
                    (p * (window.innerHeight - 10)) +
                    "px)";

                ticking = false;
            }

            window.addEventListener(
                "scroll",
                function(){
                    if (!ticking) {
                        ticking = true;
                        requestAnimationFrame(moveDot);
                    }
                },
                { passive: true }
            );

            moveDot();
        }

        /* ---------- lead capture form ---------- */

        var form = document.getElementById("enquiryForm");

        if (form) {
            var msg = document.getElementById("formMsg");
            var btn = document.getElementById("submitBtn");

            var EMAIL =
                /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

            var PHONE =
                /^[+]?[\d\s()-]{7,20}$/;

            var opened = Date.now();

            function fieldOf(el){
                return (
                    el.closest(".field") ||
                    el.closest(".consent")
                );
            }

            function validate(el){
                var ok = true;
                var v = (el.value || "").trim();

                if (el.type === "checkbox") {
                    ok = el.checked;
                } else if (el.required && !v) {
                    ok = false;
                } else if (
                    el.type === "email" &&
                    v
                ) {
                    ok = EMAIL.test(v);
                } else if (
                    el.type === "tel" &&
                    v
                ) {
                    ok = PHONE.test(v);
                }

                var wrap = fieldOf(el);

                if (wrap) {
                    wrap.classList.toggle(
                        "invalid",
                        !ok
                    );
                }

                el.setAttribute(
                    "aria-invalid",
                    ok ? "false" : "true"
                );

                return ok;
            }

            form
                .querySelectorAll("[required]")
                .forEach(function(el){

                    el.addEventListener(
                        "blur",
                        function(){
                            validate(el);
                        }
                    );

                    el.addEventListener(
                        "input",
                        function(){
                            var wrap = fieldOf(el);

                            if (
                                wrap &&
                                wrap.classList.contains(
                                    "invalid"
                                )
                            ) {
                                validate(el);
                            }
                        }
                    );

                    el.addEventListener(
                        "change",
                        function(){
                            validate(el);
                        }
                    );
                });

            function show(text, isError){
                if (!msg) {
                    return;
                }

                msg.textContent = text;

                msg.classList.toggle(
                    "is-error",
                    !!isError
                );

                msg.classList.add("show");
            }

            form.addEventListener(
                "submit",
                async function(e){

                    e.preventDefault();

                    if (msg) {
                        msg.classList.remove(
                            "show",
                            "is-error"
                        );
                    }

                    var fields =
                        Array.prototype.slice.call(
                            form.querySelectorAll(
                                "[required]"
                            )
                        );

                    var valid =
                        fields
                            .map(validate)
                            .every(Boolean);

                    if (!valid) {
                        show(
                            "Please check the highlighted fields and try again.",
                            true
                        );

                        var first =
                            form.querySelector(
                                ".invalid [required]"
                            );

                        if (first) {
                            first.focus();
                        }

                        return;
                    }

                    /*
                     * Spam guard
                     */
                    if (
                        form.website &&
                        (
                            form.website.value !== "" ||
                            (Date.now() - opened) < 2500
                        )
                    ) {
                        show(
                            "We could not submit your enquiry. Please check your details or contact us directly on 16924.",
                            true
                        );

                        return;
                    }

                    if (btn) {
                        btn.disabled = true;
                        btn.textContent =
                            "Sending…";
                    }

                    /*
                     * Read original form
                     */
                    var raw =
                        new FormData(form);

                    /*
                     * Convert frontend field names
                     * to Laravel field names
                     */
                    var payload =
                        new FormData();

                    payload.append(
                        "full_name",
                        raw.get("fullName") || ""
                    );

                    payload.append(
                        "email",
                        raw.get("email") || ""
                    );

                    payload.append(
                        "phone",
                        raw.get("phone") || ""
                    );

                    payload.append(
                        "country",
                        raw.get("country") || ""
                    );

                    payload.append(
                        "enquiry_type",
                        raw.get("enquiryType") || ""
                    );

                    payload.append(
                        "message",
                        raw.get("message") || ""
                    );

                    payload.append(
                        "launch_list",
                        raw.has("launchList")
                            ? "1"
                            : "0"
                    );

                    payload.append(
                        "consent",
                        raw.has("consent")
                            ? "1"
                            : "0"
                    );

                    payload.append(
                        "company_website",
                        raw.get("website") || ""
                    );

                    payload.append(
                        "source",
                        "homepage-new"
                    );

                    try {

                        var csrf =
                            document
                                .querySelector(
                                    'meta[name="csrf-token"]'
                                )
                                ?.getAttribute(
                                    "content"
                                );

                        if (!csrf) {
                            throw new Error(
                                "CSRF token is missing."
                            );
                        }

                        var response =
                            await fetch(
                                "/leads",
                                {
                                    method: "POST",

                                    headers: {
                                        "Accept":
                                            "application/json",

                                        "X-Requested-With":
                                            "XMLHttpRequest",

                                        "X-CSRF-TOKEN":
                                        csrf
                                    },

                                    body: payload
                                }
                            );

                        var data =
                            await response
                                .json()
                                .catch(function(){
                                    return {};
                                });

                        /*
                         * Laravel validation
                         */
                        if (
                            response.status === 422
                        ) {

                            var fieldMap = {
                                full_name:
                                    "fullName",

                                email:
                                    "email",

                                phone:
                                    "phone",

                                country:
                                    "country",

                                enquiry_type:
                                    "enquiryType",

                                message:
                                    "message",

                                launch_list:
                                    "launchList",

                                consent:
                                    "consent"
                            };

                            Object
                                .entries(
                                    data.errors || {}
                                )
                                .forEach(
                                    function(
                                        [fieldName, errors]
                                    ){

                                        var htmlName =
                                            fieldMap[fieldName];

                                        if (!htmlName) {
                                            return;
                                        }

                                        var input =
                                            form.querySelector(
                                                '[name="' +
                                                htmlName +
                                                '"]'
                                            );

                                        if (!input) {
                                            return;
                                        }

                                        var wrap =
                                            fieldOf(input);

                                        if (wrap) {

                                            wrap.classList.add(
                                                "invalid"
                                            );

                                            var errorElement =
                                                wrap.querySelector(
                                                    ".err"
                                                );

                                            if (
                                                errorElement &&
                                                errors &&
                                                errors[0]
                                            ) {
                                                errorElement
                                                    .textContent =
                                                    errors[0];
                                            }
                                        }
                                    }
                                );

                            show(
                                "Please check the highlighted fields and try again.",
                                true
                            );

                            return;
                        }

                        /*
                         * Any server error
                         */
                        if (!response.ok) {
                            throw new Error(
                                data.message ||
                                "The enquiry could not be submitted."
                            );
                        }

                        /*
                         * Analytics only after
                         * successful database save
                         */
                        (
                            window.dataLayer =
                                window.dataLayer || []
                        ).push({
                            event:
                                "enquiry_submit",

                            enquiry_type:
                                raw.get(
                                    "enquiryType"
                                ) || "",

                            country:
                                raw.get(
                                    "country"
                                ) || "",

                            launch_list:
                                raw.has(
                                    "launchList"
                                )
                        });

                        /*
                         * Success
                         */
                        form.reset();

                        form
                            .querySelectorAll(
                                ".invalid"
                            )
                            .forEach(
                                function(w){
                                    w.classList.remove(
                                        "invalid"
                                    );
                                }
                            );

                        show(
                            data.message ||
                            "Thank you. Your enquiry has been received. A Business Bay Developments representative will contact you soon."
                        );

                        opened = Date.now();

                    } catch (error) {

                        console.error(
                            "Lead form error:",
                            error
                        );

                        show(
                            "We could not submit your enquiry. Please check your details or contact us directly on 16924.",
                            true
                        );

                    } finally {

                        if (btn) {
                            btn.disabled = false;
                            btn.textContent =
                                "Send enquiry";
                        }
                    }
                }
            );
        }

        /* ---------- motion layer (GSAP + ScrollTrigger) ---------- */

        window.addEventListener(
            "load",
            function(){

                if (
                    reduced ||
                    !window.gsap ||
                    !window.ScrollTrigger
                ) {
                    return;
                }

                gsap.registerPlugin(
                    ScrollTrigger
                );

                var REVEAL =
                    ".eyebrow, .h2, .manifesto h2, .manifesto__note, .lede, .split__body, " +
                    ".disc > div, .card, .market, .markets-note, .leader, .stat, .stats__note, " +
                    ".sector, .corridor, .horizon, .closing li, .closing h2, .teaser__dot, " +
                    ".btn, .link-arrow, .form-panel, .contact-row";

                var heroBits =
                    document.querySelectorAll(
                        ".hero .eyebrow, .hero h1, .hero .lede, .hero__cta .btn, .hero__meta"
                    );

                gsap.set(
                    heroBits,
                    {
                        opacity: 0,
                        y: 26
                    }
                );

                gsap
                    .timeline({
                        defaults: {
                            ease:
                                "power3.out"
                        }
                    })
                    .to(
                        heroBits,
                        {
                            opacity: 1,
                            y: 0,
                            duration: 1,
                            stagger: 0.11
                        },
                        0.15
                    )
                    .from(
                        ".hero__bg img",
                        {
                            scale: 1.08,
                            duration: 2.2,
                            ease:
                                "power2.out"
                        },
                        0
                    );

                gsap.utils
                    .toArray(
                        "main > section, footer"
                    )
                    .forEach(
                        function(section){

                            if (
                                section
                                    .classList
                                    .contains("hero")
                            ) {
                                return;
                            }

                            var items =
                                section.querySelectorAll(
                                    REVEAL
                                );

                            if (!items.length) {
                                return;
                            }

                            gsap.set(
                                items,
                                {
                                    opacity: 0,
                                    y: 24
                                }
                            );

                            gsap.to(
                                items,
                                {
                                    opacity: 1,
                                    y: 0,
                                    duration: 0.85,
                                    ease:
                                        "power2.out",
                                    stagger: 0.07,

                                    scrollTrigger: {
                                        trigger:
                                        section,

                                        start:
                                            "top 82%",

                                        once:
                                            true
                                    }
                                }
                            );
                        }
                    );

                gsap.utils
                    .toArray(
                        ".split__media img, .leader__img img"
                    )
                    .forEach(
                        function(img){

                            gsap.fromTo(
                                img,

                                {
                                    clipPath:
                                        "inset(0% 0% 100% 0%)",
                                    scale: 1.12
                                },

                                {
                                    clipPath:
                                        "inset(0% 0% 0% 0%)",
                                    scale: 1,
                                    duration: 1.3,
                                    ease:
                                        "power3.out",

                                    scrollTrigger: {
                                        trigger:
                                        img,

                                        start:
                                            "top 88%",

                                        once:
                                            true
                                    }
                                }
                            );
                        }
                    );

                gsap.utils
                    .toArray(
                        ".counter"
                    )
                    .forEach(
                        function(el){

                            var target =
                                parseFloat(
                                    el.dataset.count
                                );

                            var obj = {
                                v: 0
                            };

                            gsap.to(
                                obj,
                                {
                                    v: target,
                                    duration: 1.6,
                                    ease:
                                        "power2.out",

                                    onUpdate:
                                        function(){
                                            el.textContent =
                                                Math.round(
                                                    obj.v
                                                );
                                        },

                                    scrollTrigger: {
                                        trigger:
                                        el,

                                        start:
                                            "top 88%",

                                        once:
                                            true
                                    }
                                }
                            );
                        }
                    );

                ScrollTrigger.matchMedia({

                    "(min-width: 900px)":
                        function(){

                            gsap.to(
                                ".hero__bg img",
                                {
                                    yPercent: 12,
                                    ease: "none",

                                    scrollTrigger: {
                                        trigger:
                                            ".hero",

                                        start:
                                            "top top",

                                        end:
                                            "bottom top",

                                        scrub:
                                            true
                                    }
                                }
                            );

                            gsap.utils
                                .toArray(
                                    ".split__media"
                                )
                                .forEach(
                                    function(m){

                                        gsap.fromTo(
                                            m.querySelector(
                                                "img"
                                            ),

                                            {
                                                yPercent:
                                                    -4
                                            },

                                            {
                                                yPercent:
                                                    4,

                                                ease:
                                                    "none",

                                                scrollTrigger: {
                                                    trigger:
                                                    m,

                                                    start:
                                                        "top bottom",

                                                    end:
                                                        "bottom top",

                                                    scrub:
                                                        1
                                                }
                                            }
                                        );
                                    }
                                );
                        }
                });

                ScrollTrigger.refresh();
            }
        );

    })();
</script>
</body>
</html>
@endverbatim
